import { describe, expect, it } from 'vitest'
import {
  ENROLLMENT_MODE,
  EnrollmentConfig,
  extractPdsEndpoint,
  isDidAllowed,
  isPdsAllowed,
  validateEnrollmentEligibility,
} from '../src/index.js'

describe('Enrollment Domain Logic', () => {
  describe('extractPdsEndpoint', () => {
    it('should extract PDS endpoint from DID document', () => {
      const didDoc = {
        service: [
          {
            id: '#atproto_pds',
            type: 'AtprotoPersonalDataServer',
            serviceEndpoint: 'https://bsky.social',
          },
        ],
      }

      const result = extractPdsEndpoint(didDoc)
      expect(result).toBe('https://bsky.social')
    })

    it('should return null if no service array', () => {
      const didDoc = {}
      const result = extractPdsEndpoint(didDoc)
      expect(result).toBeNull()
    })

    it('should return null if no PDS service found', () => {
      const didDoc = {
        service: [
          {
            id: '#other',
            type: 'Other',
            serviceEndpoint: 'https://example.com',
          },
        ],
      }

      const result = extractPdsEndpoint(didDoc)
      expect(result).toBeNull()
    })

    it('should handle full service ID with DID prefix', () => {
      const didDoc = {
        service: [
          {
            id: 'did:plc:abc123#atproto_pds',
            type: 'AtprotoPersonalDataServer',
            serviceEndpoint: 'https://pds.example.com',
          },
        ],
      }

      const result = extractPdsEndpoint(didDoc)
      expect(result).toBe('https://pds.example.com')
    })
  })

  describe('isDidAllowed', () => {
    it('should allow any DID in open mode', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.OPEN,
        allowedDids: [],
        allowedPdsEndpoints: [],
      }

      expect(isDidAllowed(config, 'did:plc:random')).toBe(true)
    })

    it('should only allowlisted DIDs in allowlist mode', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.ALLOWLIST,
        allowedDids: ['did:plc:allowed1', 'did:plc:allowed2'],
        allowedPdsEndpoints: [],
      }

      expect(isDidAllowed(config, 'did:plc:allowed1')).toBe(true)
      expect(isDidAllowed(config, 'did:plc:notallowed')).toBe(false)
    })
  })

  describe('isPdsAllowed', () => {
    it('should allow any PDS in open mode', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.OPEN,
        allowedDids: [],
        allowedPdsEndpoints: [],
      }

      expect(isPdsAllowed(config, 'https://any.pds')).toBe(true)
    })

    it('should only allowlisted PDS endpoints in allowlist mode', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.ALLOWLIST,
        allowedDids: [],
        allowedPdsEndpoints: ['https://bsky.social', 'https://pds.example.com'],
      }

      expect(isPdsAllowed(config, 'https://bsky.social')).toBe(true)
      expect(isPdsAllowed(config, 'https://pds.example.com')).toBe(true)
      expect(isPdsAllowed(config, 'https://other.pds')).toBe(false)
    })

    it('should normalize trailing slashes', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.ALLOWLIST,
        allowedDids: [],
        allowedPdsEndpoints: ['https://bsky.social/'],
      }

      expect(isPdsAllowed(config, 'https://bsky.social')).toBe(true)
    })
  })

  describe('validateEnrollmentEligibility', () => {
    it('should allow enrollment in open mode', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.OPEN,
        allowedDids: [],
        allowedPdsEndpoints: [],
      }

      const result = validateEnrollmentEligibility(
        config,
        'did:plc:test',
        'https://bsky.social',
      )

      expect(result.allowed).toBe(true)
      expect(result.pdsEndpoint).toBe('https://bsky.social')
    })

    it('should allow in open mode even without PDS endpoint', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.OPEN,
        allowedDids: [],
        allowedPdsEndpoints: [],
      }

      const result = validateEnrollmentEligibility(config, 'did:plc:test', null)

      expect(result.allowed).toBe(true)
      expect(result.pdsEndpoint).toBeUndefined()
    })

    it('should allow DID in allowlist', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.ALLOWLIST,
        allowedDids: ['did:plc:allowed'],
        allowedPdsEndpoints: [],
      }

      const result = validateEnrollmentEligibility(
        config,
        'did:plc:allowed',
        'https://bsky.social',
      )

      expect(result.allowed).toBe(true)
    })

    it('should allow PDS endpoint in allowlist', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.ALLOWLIST,
        allowedDids: [],
        allowedPdsEndpoints: ['https://bsky.social'],
      }

      const result = validateEnrollmentEligibility(
        config,
        'did:plc:random',
        'https://bsky.social',
      )

      expect(result.allowed).toBe(true)
    })

    it('should deny if neither DID nor PDS is in allowlist', () => {
      const config: EnrollmentConfig = {
        mode: ENROLLMENT_MODE.ALLOWLIST,
        allowedDids: ['did:plc:other'],
        allowedPdsEndpoints: ['https://other.pds'],
      }

      const result = validateEnrollmentEligibility(
        config,
        'did:plc:test',
        'https://bsky.social',
      )

      expect(result.allowed).toBe(false)
      expect(result.reason).toBe('NotInAllowlist')
    })
  })
})

tests/errors.test.ts.source:
import { describe, expect, it } from 'vitest'
import {
  BlobAccessDeniedError,
  BoundaryNotAllowedError,
  EnrollmentDeniedError,
  InvalidIdentifierError,
  MstError,
  NotEnrolledError,
  RecordNotFoundError,
  StratosError,
} from '../src'

describe('Domain Errors', () => {
  it('StratosError should have correct properties', () => {
    const error = new StratosError('Explosion in Tokyo-3', 'TEST_ERROR', {
      cause: 'Angel attack',
    })
    expect(error.message).toBe('Explosion in Tokyo-3')
    expect(error.code).toBe('TEST_ERROR')
    expect(error.cause).toBe('Angel attack')
    expect(error.name).toBe('StratosError')
  })

  it('NotEnrolledError should format message correctly', () => {
    const error = new NotEnrolledError('did:plc:shinji')
    expect(error.message).toBe('User did:plc:shinji is not enrolled')
    expect(error.code).toBe('NotEnrolled')
    expect(error.name).toBe('NotEnrolledError')
  })

  it('EnrollmentDeniedError should store reason', () => {
    const error = new EnrollmentDeniedError('Denied', 'NotInAllowlist')
    expect(error.message).toBe('Denied')
    expect(error.reason).toBe('NotInAllowlist')
    expect(error.code).toBe('EnrollmentDenied')
  })

  it('BoundaryNotAllowedError should format message correctly', () => {
    const error = new BoundaryNotAllowedError('geo:tokyo-2')
    expect(error.message).toBe("Boundary 'geo:tokyo-2' not allowed")
    expect(error.code).toBe('ForbiddenBoundary')
  })

  it('RecordNotFoundError should format message correctly', () => {
    const error = new RecordNotFoundError(
      'at://did:plc:rei/zone.stratos.feed.post/123',
    )
    expect(error.message).toBe(
      'Record not found: at://did:plc:rei/zone.stratos.feed.post/123',
    )
    expect(error.code).toBe('RecordNotFound')
  })

  it('InvalidIdentifierError should have correct code', () => {
    const error = new InvalidIdentifierError('Bad CID')
    expect(error.message).toBe('Bad CID')
    expect(error.code).toBe('InvalidIdentifier')
  })

  it('MstError should have correct code', () => {
    const error = new MstError('MST failure')
    expect(error.message).toBe('MST failure')
    expect(error.code).toBe('MstError')
  })

  it('BlobAccessDeniedError should format message correctly', () => {
    const error = new BlobAccessDeniedError('bafybeig')
    expect(error.message).toBe('Access denied to blob: bafybeig')
    expect(error.code).toBe('BlobAccessDenied')
  })
})

